'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var instanceOf = require( '@stdlib/assert/instance-of' );
var isBoolean = require( '@stdlib/assert/is-boolean' ).isPrimitive;
var isNumber = require( '@stdlib/assert/is-number' ).isPrimitive;
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var isPlainObject = require( '@stdlib/assert/is-plain-object' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var Value = require( './../lib' );


// MAIN //

bench( format( '%s::instantiation', pkg ), function benchmark( b ) {
	var v;
	var i;

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v = new Value();
		if ( !instanceOf( v, Value ) ) {
			b.fail( 'should return an instance' );
		}
	}
	b.toc();
	if ( !instanceOf( v, Value ) ) {
		b.fail( 'should return an instance' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s::instantiation,no_new', pkg ), function benchmark( b ) {
	var ctor;
	var v;
	var i;

	ctor = Value;

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v = ctor();
		if ( !instanceOf( v, Value ) ) {
			b.fail( 'should return an instance' );
		}
	}
	b.toc();
	if ( !instanceOf( v, Value ) ) {
		b.fail( 'should return an instance' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s::instantiation,options', pkg ), function benchmark( b ) {
	var opts;
	var v;
	var i;

	opts = {
		'field': 'price',
		'scale': 'xScale',
		'mult': 2,
		'round': true
	};

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v = new Value( opts );
		if ( !instanceOf( v, Value ) ) {
			b.fail( 'should return an instance' );
		}
	}
	b.toc();
	if ( !instanceOf( v, Value ) ) {
		b.fail( 'should return an instance' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s::set,get:band', pkg ), function benchmark( b ) {
	var values;
	var v;
	var i;

	values = [
		0.25,
		0.5,
		1
	];
	v = new Value();

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v.band = values[ i % values.length ];
		if ( !isNumber( v.band ) ) {
			b.fail( 'should return a number' );
		}
	}
	b.toc();
	if ( !isNumber( v.band ) ) {
		b.fail( 'should return a number' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s::set,get:color', pkg ), function benchmark( b ) {
	var values;
	var v;
	var i;

	values = [
		{
			'r': {
				'value': 255
			},
			'g': {
				'value': 0
			},
			'b': {
				'value': 0
			}
		},
		{
			'r': {
				'value': 0
			},
			'g': {
				'value': 0
			},
			'b': {
				'value': 255
			}
		}
	];
	v = new Value();

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v.color = values[ i % values.length ];
		if ( typeof v.color !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !isPlainObject( v.color ) ) {
		b.fail( 'should return an object' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

